// Ingest is the full per-entity flow (artwork): Acquire the upstream url
// (fetch-once), ensure the center-cropped 2:3 JPEG sits beside the stored
// original (always JPEG q85, never upscaled), pin the entity's override on
// the art_<sha256> token, and — when this replaces the entity's previous
// upload — delete the old blob pair. Returns the token the path-serve
// resolves from. An empty kind defaults to KindPoster.
func (s *Service) Ingest(ctx context.Context, entityID, entityKind, url, kind string) (string, error) {
	if kind == "" {
		kind = KindPoster
	}
	sha, err := s.Acquire(ctx, url, kind)
	if err != nil {
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	}
	return s.pin(ctx, entityID, entityKind, sha)
}

// IngestBytes is the upload entry (artwork): the bytes pass the SAME guard
// fetched bytes do — the ≤8 MiB re-check, the magic sniff, the real decode —
// then ride the identical crop-and-pin flow as a fetched poster. The api
// route caps the request body as transport hygiene; this guard is the
// authoritative size check. An empty kind defaults to KindPoster.
func (s *Service) IngestBytes(ctx context.Context, entityID, entityKind string, body []byte, kind string) (string, error) {
	if kind == "" {
		kind = KindPoster
	}
	ext, err := guard(body)
	if err != nil {
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	}
	sha := sha256Hex(body)
	if err := s.storeOriginal(sha, ext, body); err != nil {
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	}
	return s.pin(ctx, entityID, entityKind, sha)
}

// pin is the shared tail of both ingest entries: derive the cropped 2:3
// beside the stored original, delete the pair a replacement displaces, and
// pin the entity's override on the art_<sha256> token — which this returns
// for the path-serve to resolve from.
func (s *Service) pin(ctx context.Context, entityID, entityKind, sha string) (string, error) {
	token := "art_" + sha
	if err := s.ensureCropped(sha); err != nil {
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	}
	old, err := s.st.GetArtOverride(ctx, entityID, entityKind)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// First art for this entity — nothing to replace.
	case err != nil:
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	case old != token:
		// Replacing an upload: the old pair (original + cropped) dies with
		// the replace. Only a parseable art token is removed — a foreign
		// selection is left alone. A stale fetch row still pointing at the
		// removed blob self-heals on the next Acquire (the disk check
		// re-fetches and re-points the row).
		if oldSHA, ok := tokenSHA(old); ok {
			if err := os.RemoveAll(filepath.Join(s.dir, oldSHA)); err != nil {
				return "", fmt.Errorf("art: ingest %s/%s: remove old pair: %w", entityID, entityKind, err)
			}
		}
	}
	if _, err := s.st.UpsertArtOverride(ctx, entityID, entityKind, token); err != nil {
		return "", fmt.Errorf("art: ingest %s/%s: %w", entityID, entityKind, err)
	}
	return token, nil
}

// ensureCropped writes <root>/<sha>/cropped.jpg from the stored original
// when absent: the real decode, the crop-once 2:3 without upscaling, and
// the q85 re-encode. Idempotent — the crop is derived content, byte-identical
// every recompute.
func (s *Service) ensureCropped(sha string) error {
	cropped := filepath.Join(s.dir, sha, croppedFile)
	if _, err := os.Stat(cropped); err == nil {
		return nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("art: crop %s: %w", sha, err)
	}
	orig, err := findOriginal(filepath.Join(s.dir, sha))
	if err != nil {
		return fmt.Errorf("art: crop %s: %w", sha, err)
	}
	body, err := os.ReadFile(orig)
	if err != nil {
		return fmt.Errorf("art: crop %s: %w", sha, err)
	}
	img, _, err := image.Decode(bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("art: crop %s: decode: %w", sha, err)
	}
	rect := cropCenter23(img)
	sub, ok := img.(interface {
		SubImage(r image.Rectangle) image.Image
	})
	if !ok {
		return fmt.Errorf("art: crop %s: decoded type %T cannot be cropped", sha, img)
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, sub.SubImage(rect), &jpeg.Options{Quality: croppedQuality}); err != nil {
		return fmt.Errorf("art: crop %s: encode: %w", sha, err)
	}
	if err := writeFileAtomic(cropped, buf.Bytes()); err != nil {
		return fmt.Errorf("art: crop %s: %w", sha, err)
	}
	return nil
}

// cropCenter23 returns the largest CENTERED 2:3 rectangle inside img — one
// crop, no resample passes, never an upscale: the rectangle is always a
// strict sub-rectangle of the frame (an already-2:3 frame comes back whole;
// the integer floor costs sub-percent aspect slack at worst).
func cropCenter23(img image.Image) image.Rectangle {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	cw, ch := w, h
	switch {
	case w*3 > h*2: // wider than 2:3 — trim the sides
		cw = h * 2 / 3
	case w*3 < h*2: // taller — trim top and bottom
		ch = w * 3 / 2
	}
	x0 := b.Min.X + (w-cw)/2
	y0 := b.Min.Y + (h-ch)/2
	return image.Rect(x0, y0, x0+cw, y0+ch)
}

// findOriginal locates the one original.* in a blob dir. A missing blob is
// a wrapped os.ErrNotExist (404-able); more than one is a corrupted tree.
func findOriginal(dir string) (string, error) {
	hits, err := filepath.Glob(filepath.Join(dir, originalPrefix+"*"))
	if err != nil {
		return "", fmt.Errorf("find original in %s: %w", dir, err)
	}
	if len(hits) == 0 {
		return "", fmt.Errorf("find original in %s: %w", dir, os.ErrNotExist)
	}
	if len(hits) > 1 {
		return "", fmt.Errorf("find original in %s: %d candidates", dir, len(hits))
	}
	return hits[0], nil
}
